        }

        .search-bar-hero {
            background: var(--white);
            border-bottom: 1px solid #eee;
            padding: 20px 0;
        }

        .search-bar-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
            display: flex;
            gap: 10px;
            align-items: center;
        }

        .search-bar-container a {
            font-size: 14px;
            color: var(--text-light);
        }

