            flex: 1;
            padding: 10px 15px;
            border: 1px solid #ddd;
            border-radius: 20px;
            outline: none;
        }

        .search-bar-container input:focus {
            border-color: var(--primary-color);
        }

        /* Main Content */
        .main-container {
            max-width: 1200px;
            margin: 30px auto;
            padding: 0 20px;
            display: grid;
            grid-template-columns: 250px 1fr;
            gap: 30px;
        }

        /* Sidebar Filters */
        .filters {
            background: var(--white);
            padding: 20px;
            border-radius: var(--border-radius);
            height: fit-content;
        }

        .filter-section {
            margin-bottom: 25px;
        }

        .filter-section h3 {
            font-size: 16px;
            margin-bottom: 15px;
            border-left: 3px solid var(--primary-color);
            padding-left: 10px;
        }

        .checkbox-group label {
            display: flex;
            align-items: center;
            margin-bottom: 8px;
            font-size: 14px;
            color: var(--text-light);
            cursor: pointer;
        }

        .checkbox-group input {
            margin-right: 8px;
        }

        /* Results List */
        .results-header {
            margin-bottom: 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .results-header h2 {
            font-size: 20px;
        }

        .sort-select {
            padding: 8px 12px;
            border: 1px solid #ddd;
            border-radius: 4px;
        }

        .hotel-list {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .hotel-card {
            background: var(--white);
            border-radius: var(--border-radius);
            overflow: hidden;
            display: grid;
            grid-template-columns: 280px 1fr;
            box-shadow: var(--shadow);
            transition: transform 0.2s;
        }

        .hotel-card:hover {
            transform: translateY(-2px);
        }

        .hotel-image {
            position: relative;
            background: #eee;
        }

        .hotel-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            min-height: 200px;
        }

        .hotel-tag {
            position: absolute;
            top: 10px;
            left: 10px;
            background: var(--secondary-color);
            color: #fff;
            padding: 2px 8px;
            font-size: 12px;
            border-radius: 2px;
            font-weight: bold;
        }

