            color: var(--secondary-color);
            font-weight: bold;
            font-size: 14px;
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .price-action {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-top: 1px solid #eee;
            padding-top: 15px;
        }

        .price-info {
            display: flex;
            flex-direction: column;
        }

        .price-label {
            font-size: 12px;
            color: var(--text-light);
        }

        .price-value {
            font-size: 24px;
            font-weight: bold;
            color: #d93025;
        }

        .btn-select {
            padding: 10px 25px;
            background: var(--primary-color);
            color: var(--white);
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: 600;
        }

        .btn-select:hover {
            background: var(--primary-dark);
        }

        /* Footer */
        footer {
            background: #222;
            color: #aaa;
            padding: 40px 0;
            margin-top: 60px;
            text-align: center;
        }

        @media (max-width: 768px) {
            .main-container {
                grid-template-columns: 1fr;
            }
            .hotel-card {
                grid-template-columns: 1fr;
            }
            .hotel-image {
                height: 200px;
            }
            .filters {
                display: none;
            }
        }
    </style>
</head>
